"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type CSSProperties, useEffect, useId, useRef, useState } from "react";

import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";

import { formatOnePlace } from "../lib/format";
import { BlockFrame } from "../parts/block-frame";
import { CheckIcon, ChevronRightIcon, CircleCheckIcon, packIcon, RefreshIcon } from "../parts/icons";
import { RollingText } from "../parts/rolling-text";
import { HeartIcon, TruckIcon } from "./icons";
import { formatDollars } from "./money";
import { DETAILS, FINISHES, REVIEW_COUNTS, STOOL_SIZES } from "./product-detail/data";
import { Gallery } from "./product-detail/gallery";
import { OptionGroup } from "./product-detail/option-group";
import { QuantityStepper } from "./product-detail/quantity-stepper";
import { ReviewsSummary } from "./product-detail/reviews-summary";
import { StarRow } from "./product-detail/star-row";

const BagIcon = packIcon("shopping-bag");
const NAME = "Willow treatment stool";
const RATING = 4.6;

/**
 * A product page for a treatment stool: swipe through its pictures, pick a
 * finish and a size, set the quantity and add it to the bag, which confirms
 * in place. The price rolls when the size or quantity changes.
 */
export function ProductDetail({ className }: { className?: string }) {
  const titleId = useId();
  const reduceMotion = useReducedMotion();
  const [finishId, setFinishId] = useState(FINISHES[0]!.id);
  const [sizeId, setSizeId] = useState(STOOL_SIZES[0]!.id);
  const [quantity, setQuantity] = useState(1);
  const [favourite, setFavourite] = useState(false);
  const [bag, setBag] = useState(0);
  const [justAdded, setJustAdded] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => () => {
    if (timer.current) clearTimeout(timer.current);
  }, []);

  const finish = FINISHES.find((item) => item.id === finishId) ?? FINISHES[0]!;
  const size = STOOL_SIZES.find((item) => item.id === sizeId) ?? STOOL_SIZES[0]!;

  const addToBag = () => {
    setBag((count) => count + quantity);
    setJustAdded(true);
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => setJustAdded(false), 2000);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex items-center justify-between gap-3 border-b border-border px-5 py-3">
        <nav aria-label="Breadcrumb">
          <ol className="flex items-center gap-1 text-sm text-muted-foreground">
            <li>Clinic shop</li>
            <li aria-hidden="true">
              <ChevronRightIcon className="size-3.5" />
            </li>
            <li>Seating</li>
            <li aria-hidden="true">
              <ChevronRightIcon className="size-3.5" />
            </li>
            <li aria-current="page" className="truncate text-foreground">
              {NAME}
            </li>
          </ol>
        </nav>
        <Button type="button" variant="ghost" size="sm" aria-label={`Bag, ${bag} ${bag === 1 ? "item" : "items"}`}>
          <BagIcon aria-hidden="true" className="size-4" />
          <RollingText text={String(bag)} />
        </Button>
      </header>

      <div className="grid gap-8 p-5 @3xl:grid-cols-2">
        <Gallery finish={finish} productName={NAME} />

        <div className="flex flex-col gap-5">
          <div className="flex flex-col gap-2">
            <div className="flex items-start justify-between gap-3">
              <h2 id={titleId} className="text-2xl font-semibold tracking-tight">
                {NAME}
              </h2>
              <Button
                type="button"
                variant="outline"
                size="icon"
                aria-pressed={favourite}
                aria-label="Save to favourites"
                onClick={() => setFavourite((value) => !value)}
              >
                <HeartIcon aria-hidden="true" className={favourite ? "size-4 fill-current text-chart-5" : "size-4"} />
              </Button>
            </div>
            <div className="flex flex-wrap items-center gap-3">
              <RollingText text={formatDollars(size.price)} className="text-xl font-medium" />
              <span className="flex items-center gap-1.5 text-sm text-muted-foreground">
                <StarRow rating={RATING} />
                {formatOnePlace(RATING)} (212)
              </span>
            </div>
            <p className="text-sm text-muted-foreground">
              A low, steady stool for treatment rooms. The seat rises and sinks with one lever, and the castors roll quietly on clinic floors.
            </p>
          </div>

          <OptionGroup
            legend="Finish"
            chosen={finish.name}
            look="swatch"
            value={finishId}
            onChange={setFinishId}
            options={FINISHES.map((item) => ({
              id: item.id,
              label: item.name,
              content: (
                <span
                  aria-hidden="true"
                  className="block size-7 rounded-full border border-border bg-(--tone)"
                  // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                  style={{ "--tone": item.tone } as CSSProperties}
                />
              ),
            }))}
          />

          <OptionGroup
            legend="Size"
            chosen={size.height}
            look="card"
            value={sizeId}
            onChange={setSizeId}
            options={STOOL_SIZES.map((item) => ({
              id: item.id,
              label: `${item.name}, ${item.height}, ${formatDollars(item.price)}`,
              content: (
                <span aria-hidden="true" className="flex flex-col">
                  <span className="text-sm font-medium">{item.name}</span>
                  <span className="text-xs text-muted-foreground">{formatDollars(item.price)}</span>
                </span>
              ),
            }))}
          />

          <div className="flex items-center gap-2">
            <QuantityStepper value={quantity} onChange={setQuantity} />
            <Button type="button" size="lg" onClick={addToBag} className="flex-1">
              <AnimatePresence mode="wait" initial={false}>
                <motion.span
                  key={justAdded ? "added" : "add"}
                  initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
                  transition={{ duration: 0.15 }}
                  className="flex items-center gap-1.5"
                >
                  {justAdded ? (
                    <>
                      <CheckIcon aria-hidden="true" className="size-4" />
                      Added to bag
                    </>
                  ) : (
                    <>
                      Add to bag, <RollingText text={formatDollars(size.price * quantity)} />
                    </>
                  )}
                </motion.span>
              </AnimatePresence>
            </Button>
          </div>
          <p role="status" className="sr-only">
            {justAdded ? `Added ${quantity} ${NAME} in ${finish.name}, ${size.name}, to the bag.` : ""}
          </p>

          <ul className="flex flex-col gap-2 border-y border-border py-4 text-sm">
            <li className="flex items-center gap-2">
              <TruckIcon aria-hidden="true" className="size-4 text-muted-foreground" />
              <span className="font-medium">Free delivery</span>
              <span className="text-muted-foreground">Arrives Nov 16 to 18</span>
            </li>
            <li className="flex items-center gap-2">
              <RefreshIcon aria-hidden="true" className="size-4 text-muted-foreground" />
              <span className="font-medium">30 day returns</span>
              <span className="text-muted-foreground">We collect it for free</span>
            </li>
            <li className="flex items-center gap-2">
              <CircleCheckIcon aria-hidden="true" className="size-4 text-muted-foreground" />
              <span className="font-medium">Five year warranty</span>
              <span className="text-muted-foreground">Covers the lift and base</span>
            </li>
          </ul>

          <section aria-label="Reviews">
            <ReviewsSummary counts={REVIEW_COUNTS} />
          </section>

          <Accordion type="single" collapsible defaultValue="materials">
            {DETAILS.map((item) => (
              <AccordionItem key={item.id} value={item.id}>
                <AccordionTrigger>{item.title}</AccordionTrigger>
                <AccordionContent>
                  <p className="text-muted-foreground">{item.body}</p>
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        </div>
      </div>
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

