import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

/** The things the commerce blocks draw. Every drawing is our own, made of plain shapes. */
export type SupplyKind =
  | "scrub-top"
  | "scrub-trousers"
  | "lab-coat"
  | "clog"
  | "cap"
  | "socks"
  | "stool"
  | "lamp"
  | "gloves"
  | "kit"
  | "thermometer"
  | "bandage";

/** Props for one product drawing. */
export interface SupplyArtProps {
  kind: SupplyKind;
  /** The product's colour, as an `oklch()` value. */
  tone: string;
  /** The second view swaps the angle, for a card's hover picture or a gallery's next frame. */
  view?: "front" | "back" | "detail" | "scene";
  /** Cover fills a frame of another shape, such as a square thumbnail, and crops the edges. */
  fit?: "contain" | "cover";
  className?: string;
}

// Each drawing sits in a 100 by 125 box, the 4:5 frame the cards use.
// A drawn product keeps its own paint in every design system, as a real object would. Only these fixed paints and the product's tone are used.
const PAINT = {
  castor: "oklch(0.3 0.01 260)",
  white: "oklch(1 0 0)",
  window: "oklch(1 0 0 / 0.7)",
  shadow: "oklch(0 0 0 / 0.08)",
