}

/**
 * Draws one product in a 4:5 frame from plain shapes, tinted with the
 * product's colour. It is decorative: the product's name says what it is.
 */
export function SupplyArt({ kind, tone, view = "front", fit = "contain", className }: SupplyArtProps) {
  const back = view === "back";
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      viewBox="0 0 100 125"
      preserveAspectRatio={fit === "cover" ? "xMidYMid slice" : "xMidYMid meet"}
      className={cn("size-full", className)}>
      <rect width="100" height="125" fill={`color-mix(in oklch, ${tone} 14%, oklch(0.97 0.006 80))`} />
      {view === "scene" ? (
        <>
          <rect y="100" width="100" height="25" fill={`color-mix(in oklch, ${tone} 22%, oklch(0.86 0.01 80))`} />
          <rect x="8" y="14" width="26" height="34" rx="2" fill={PAINT.window} />
        </>
      ) : (
        <ellipse cx="50" cy="108" rx="30" ry="4" fill={PAINT.shadow} />
      )}
      <g transform={view === "detail" ? "translate(-50 -62) scale(2)" : view === "scene" ? "translate(20 12) scale(0.75)" : undefined}>
        {drawing(kind, tone, back)}
      </g>
    </svg>
  );
}

"use client";

import { animate, AnimatePresence, motion, type MotionStyle, useMotionValue, useReducedMotion, useTransform } from "motion/react";
import { type PointerEvent, useCallback, useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { SupplyArt } from "../supply-art";
import { type Finish, VIEWS } from "./data";

/** Props for the product gallery. */
export interface GalleryProps {
  finish: Finish;
  productName: string;
}

// Critically damped enough to land without a wobble, soft enough to carry a flick's speed.
const SLIDE = { type: "spring" as const, stiffness: 320, damping: 36, mass: 1 };
// How far a flick carries past the release point: the velocity in pixels per second times this many seconds.
const FLICK_CARRY = 0.18;
// How much of a pull past either end the track follows, so the ends stretch rather than stop dead.
const STRETCH = 0.18;

interface Press {
  startX: number;
  startValue: number;
  lastX: number;
  lastTime: number;
  /** Pixels per second, smoothed over the last few moves. */
  velocity: number;
}

/**
 * The product's pictures. The track follows the pointer one to one, stretches
 * at either end, and on release carries the flick's speed into the spring
 * that lands on the nearest picture. Arrows step through the pictures and the
 * thumbnails jump to one. A new finish crossfades each picture in place.
 */
export function Gallery({ finish, productName }: GalleryProps) {
  const reduceMotion = useReducedMotion();
  const ringId = useId();
  const viewport = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);
  const [index, setIndex] = useState(0);
  const indexRef = useRef(0);
  const x = useMotionValue(0);
  const widthRef = useRef(1);
  // The track moves by a share of its own width, so the offset needs no pixel unit.
  const slide = useTransform(x, (value) => `${(value / widthRef.current) * 100}%`);
  const press = useRef<Press | null>(null);
  const last = VIEWS.length - 1;

  useEffect(() => {
    const element = viewport.current;
    if (!element) return;
    const observer = new ResizeObserver(([entry]) => {
      const next = entry?.contentRect.width ?? 0;
      setWidth(next);
      widthRef.current = next || 1;
      x.set(-indexRef.current * next);
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, [x]);

  const goTo = useCallback(
    (next: number, velocity = 0) => {
      const target = Math.min(last, Math.max(0, next));
      indexRef.current = target;
      setIndex(target);
      if (reduceMotion) x.set(-target * width);
      else animate(x, -target * width, { ...SLIDE, velocity });
    },
    [last, reduceMotion, width, x],
  );

  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0 || width === 0) return;
    x.stop();
    press.current = { startX: event.clientX, startValue: x.get(), lastX: event.clientX, lastTime: event.timeStamp, velocity: 0 };
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const current = press.current;
    if (!current) return;
    const raw = current.startValue + event.clientX - current.startX;
    const end = -last * width;
    x.set(raw > 0 ? raw * STRETCH : raw < end ? end + (raw - end) * STRETCH : raw);
    const elapsed = event.timeStamp - current.lastTime;
    if (elapsed > 0) {
      const instant = ((event.clientX - current.lastX) / elapsed) * 1000;
      current.velocity = current.velocity * 0.3 + instant * 0.7;
    }
    current.lastX = event.clientX;
    current.lastTime = event.timeStamp;
  };

  const onPointerEnd = () => {
    const current = press.current;
    press.current = null;
    if (!current || width === 0) return;
    const projected = x.get() + current.velocity * FLICK_CARRY;
    goTo(Math.round(-projected / width), current.velocity);
  };

  const current = VIEWS[index] ?? VIEWS[0]!;

  return (
    <div className="flex flex-col gap-3">
      <div
        ref={viewport}
        role="region"
        aria-roledescription="carousel"
        aria-label={`Pictures of ${productName}. Use the arrow keys to see the next picture.`}
        tabIndex={0}
        onKeyDown={(event) => {
          if (event.key === "ArrowRight") goTo(index + 1);
          else if (event.key === "ArrowLeft") goTo(index - 1);
          else if (event.key === "Home") goTo(0);
          else if (event.key === "End") goTo(last);
          else return;
          event.preventDefault();
        }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerEnd}
        onPointerCancel={onPointerEnd}
        className="relative aspect-[4/5] cursor-grab touch-pan-y overflow-hidden select-none rounded-2xl border border-border outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card active:cursor-grabbing"
      >
        <motion.div
          className="flex h-full translate-x-(--slide)"
          // SAFETY: the object sets only CSS custom properties, which motion writes to the element as they are.
          style={{ "--slide": slide } as MotionStyle}
        >
          {VIEWS.map((item, position) => (
            <div key={item.view} aria-hidden={position !== index} className="relative h-full w-full shrink-0">
              <AnimatePresence initial={false}>
                <motion.div
                  key={finish.id}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  transition={{ duration: reduceMotion ? 0 : 0.3 }}
                  className="absolute inset-0"
                >
                  <SupplyArt kind="stool" tone={finish.tone} view={item.view} />
                </motion.div>
              </AnimatePresence>
            </div>
          ))}
        </motion.div>
        <span className="absolute right-3 bottom-3 rounded-full bg-card px-2 py-0.5 text-xs font-medium tabular-nums">
          {index + 1} of {VIEWS.length}
        </span>
        <p aria-live="polite" className="sr-only">
          Picture {index + 1} of {VIEWS.length}: {current.caption}, {finish.name}.
        </p>
      </div>
      <div role="group" aria-label="Choose a picture" className="grid grid-cols-4 gap-2">
        {VIEWS.map((item, position) => (
          <Button
            key={item.view}
            type="button"
            variant="ghost"
            size="icon"
            aria-label={item.caption}
            aria-current={position === index}
            onClick={() => goTo(position)}
            className="relative aspect-square h-auto w-full overflow-hidden"
          >
            <span className={cn("absolute inset-0 overflow-hidden rounded-lg border border-border", position !== index && "opacity-70")}>
              <SupplyArt kind="stool" tone={finish.tone} view={item.view} fit="cover" />
            </span>
            {position === index ? (
              <motion.span
                layoutId={ringId}
                transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 420, damping: 36 }}
                className="absolute inset-0 rounded-lg ring-2 ring-foreground ring-inset"
              />
            ) : null}
          </Button>
        ))}
      </div>
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import { useId } from "react";

import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

/** One choice in an option group. */
export interface Option {
  id: string;
  /** What a screen reader hears for the choice. */
  label: string;
  /** What the choice draws. */
  content: ReactNode;
}

/** Props for a group of choices. */
export interface OptionGroupProps {
  legend: string;
  /** The chosen choice's name, shown after the legend. */
  chosen: string;
  options: Option[];
  value: string;
  onChange: (id: string) => void;
  /** Swatches sit in a row of circles; cards fill a grid. */
  look: "swatch" | "card";
}

/**
 * A set of choices built on the radio group, so Tab enters the group once
 * and the arrow keys move the choice. Each choice shows a focus ring and a
 * clear chosen state that does not rely on colour alone.
 */
export function OptionGroup({ legend, chosen, options, value, onChange, look }: OptionGroupProps) {
  const legendId = useId();
  return (
    <fieldset className="flex flex-col gap-2">
      <legend id={legendId} className="mb-2 text-sm">
        <span className="font-medium">{legend}</span> <span className="text-muted-foreground">{chosen}</span>
      </legend>
      <RadioGroup aria-labelledby={legendId} value={value} onValueChange={onChange} className={look === "swatch" ? "flex" : "grid-cols-2"}>
        {options.map((option) => {
          const checked = option.id === value;
          return (
            <label
              key={option.id}
              className={cn(
                "relative isolate cursor-pointer has-focus-visible:ring-2 has-focus-visible:ring-ring has-focus-visible:ring-offset-2 has-focus-visible:ring-offset-card",
                look === "swatch"
                  ? cn("rounded-full p-0.5", checked ? "ring-2 ring-foreground" : "ring-1 ring-border")
                  : cn("rounded-xl border px-3 py-2.5", checked ? "border-foreground" : "border-border hover:border-muted-foreground"),
              )}
            >
              <RadioGroupItem value={option.id} aria-label={option.label} className="sr-only" />
              {option.content}
            </label>
          );
        })}
      </RadioGroup>
    </fieldset>
  );
}

