/** Props for the quantity stepper. */
export interface QuantityStepperProps {
  value: number;
  onChange: (value: number) => void;
  min?: number;
  max?: number;
}

/**
 * Two buttons around a rolling count. The count is announced as it changes,
 * and each button stops at its end of the range.
 */
export function QuantityStepper({ value, onChange, min = 1, max = 10 }: QuantityStepperProps) {
  return (
    <div role="group" aria-label="Quantity" className="flex h-10 items-center gap-1 rounded-full border border-border px-1">
      <Button type="button" variant="ghost" size="icon" aria-label="One fewer" disabled={value <= min} onClick={() => onChange(value - 1)} className="size-8">
        <MinusIcon aria-hidden="true" className="size-4" />
      </Button>
      <span aria-live="polite" className="w-6 text-center text-sm font-medium">
        <RollingText text={String(value)} />
      </span>
      <Button type="button" variant="ghost" size="icon" aria-label="One more" disabled={value >= max} onClick={() => onChange(value + 1)} className="size-8">
