"use client";

import { type CSSProperties, useState } from "react";

import { cn } from "@/lib/utils";

import { formatOnePlace, formatWhole } from "../../lib/format";
import { StarRow } from "./star-row";

const BAR_TINT = ["bg-chart-2", "bg-chart-1", "bg-chart-4", "bg-chart-5", "bg-chart-3"];

/** Props for the reviews summary. */
export interface ReviewsSummaryProps {
  /** How many reviews gave each star count, five stars first. */
  counts: number[];
}

/**
 * The average rating and how the reviews split by star count. Hovering a
 * row shows it at full colour and fades the others. It is a list
 * with the count in words, so the bars are never the only source.
 */
export function ReviewsSummary({ counts }: ReviewsSummaryProps) {
  const [active, setActive] = useState<number | null>(null);
  const total = counts.reduce((sum, count) => sum + count, 0);
  const average = counts.reduce((sum, count, index) => sum + count * (5 - index), 0) / (total || 1);
  const largest = Math.max(...counts, 1);

  return (
    <div className="grid items-center gap-5 @md:grid-cols-[auto_1fr]">
      <div className="flex flex-col gap-1">
        <span className="text-4xl font-semibold tracking-tight">{formatOnePlace(average)}</span>
        <StarRow rating={average} />
        <span className="text-xs text-muted-foreground">{formatWhole(total)} reviews</span>
      </div>
      <ul className="flex flex-col gap-1" onPointerLeave={() => setActive(null)}>
        {counts.map((count, index) => {
          const stars = 5 - index;
          const faded = active !== null && active !== index;
          return (
            <li
              key={stars}
              onPointerEnter={() => setActive(index)}
              className="relative isolate grid grid-cols-[3.5rem_1fr_2.5rem] items-center gap-2 rounded-md px-1.5 py-1 text-xs"
            >
              <span aria-hidden="true" className={cn("absolute inset-0 -z-10 rounded-md", active === index && "bg-muted/60")} />
              <span className="text-muted-foreground">{stars} {stars === 1 ? "star" : "stars"}</span>
              <span aria-hidden="true" className="h-2 overflow-hidden rounded-full bg-border">
                <span
                  className={cn("block h-full w-(--bar) rounded-full motion-safe:transition-opacity", BAR_TINT[index], faded && "opacity-30")}
                  // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                  style={{ "--bar": `${(count / largest) * 100}%` } as CSSProperties}
                />
              </span>
              <span className="text-right tabular-nums">{count}</span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { formatOnePlace } from "../../lib/format";

/**
 * Five stars filled to a rating, such as 4.6. The stars are drawn; the
 * rating is spoken as text.
 */
export function StarRow({ rating }: { rating: number }) {
  return (
    <span className="inline-flex items-center gap-0.5 text-chart-3">
      <span className="sr-only">Rated {formatOnePlace(rating)} out of 5</span>
      {[0, 1, 2, 3, 4].map((place) => {
        const fill = Math.min(1, Math.max(0, rating - place));
        return (
          <svg key={place} aria-hidden="true" viewBox="0 0 16 16" className="size-3.5">
            <defs>
              <clipPath id={`star-fill-${place}-${Math.round(fill * 100)}`}>
                <rect width={16 * fill} height="16" />
              </clipPath>
            </defs>
            <path d="M8 1.5l1.9 4 4.3.5-3.2 3 .9 4.3L8 11.1l-3.9 2.2.9-4.3-3.2-3 4.3-.5Z" fill="none" stroke="currentColor" strokeWidth="1" />
            <path
              d="M8 1.5l1.9 4 4.3.5-3.2 3 .9 4.3L8 11.1l-3.9 2.2.9-4.3-3.2-3 4.3-.5Z"
              fill="currentColor"
              clipPath={`url(#star-fill-${place}-${Math.round(fill * 100)})`}
            />
          </svg>
        );
      })}
    </span>
  );
}
